		DataSources.inGame.player.BRData = {}
		DataSources.inGame.player.BRData.teamList = LUI.DataSourceFromList.new( 3 )
		DataSources.inGame.player.BRData.teamList.MakeDataSourceAtIndex = function ( f2_arg0, f2_arg1, f2_arg2 )
			local f2_local0 = f1_local0 - f2_arg1
			return {
				squadIndex = LUI.DataSourceInControllerModel.new( "cg.player.BRData.teamlist.squadIndex." .. f2_local0 ),
				clientNum = LUI.DataSourceInControllerModel.new( "cg.player.BRData.teamlist.clientNum." .. f2_local0 )
			}
		end
		
	end
	if CONDITIONS.@isbr() then
		InitBRStyleDataSources()
	else
		InitHealthEquipmentDataSources()
	end
end

